select d::date as date, extract(year from d)::int as year, extract(quarter from d)::int as quarter, extract(month from d)::int as month, extract(week from d)::int as week, extract(isodow from d)::int as day_of_week, to_char(d,'Month') as month_name, to_char(d,'YYYY-MM') as year_month from generate_series((select min(order_purchase_timestamp::timestamp)::date from {{ ref('stg_orders') }}),(select max(order_purchase_timestamp::timestamp)::date from {{ ref('stg_orders') }}),interval '1 day') d
